// Pin every direct dependency/devDependency of a package.json to the version currently
// installed (resolved from package-lock.json), so no real version changes; only ranges go away.
// Usage: node pin_versions.mjs <dir-with-package.json>
import { readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';

const dir = path.resolve(process.argv[2]);
const pkgPath = path.join(dir, 'package.json');
const pkg = JSON.parse(readFileSync(pkgPath, 'utf8'));
const lock = JSON.parse(readFileSync(path.join(dir, 'package-lock.json'), 'utf8'));
const changes = [];

for (const field of ['dependencies', 'devDependencies']) {
  for (const [name, spec] of Object.entries(pkg[field] ?? {})) {
    if (/^\d+\.\d+\.\d+(-[\w.]+)?$/.test(spec)) continue; // already exact
    const resolved = lock.packages?.[`node_modules/${name}`]?.version;
    if (!resolved) throw new Error(`${name}: not found in package-lock.json`);
    pkg[field][name] = resolved;
    changes.push(`${field}: ${name} ${spec} -> ${resolved}`);
  }
}
writeFileSync(pkgPath, JSON.stringify(pkg, null, 2) + '\n');
console.log(changes.length ? changes.join('\n') : 'nothing to pin');

